/ {
    /* This overlay adds a Bosch BME280 sensor on I2C0 with interrupt */
};

&i2c0 {
    status = "okay";

    bme280@76 {
        compatible = "bosch,bme280";
        reg = <0x76>;
        status = "okay";
        interrupt-parent = <&gpio0>;
        interrupts = <15 GPIO_ACTIVE_LOW>;
    };
};
